END_EXCLUSIVE = "exclusive"
DELEGATE_ALL = "all"
DELEGATE_OWNED = "owned"
DELEGATE_NONE = "none"

_ROLES = (ROLE_EXACT, ROLE_LOWER, ROLE_FOLDED)
_SUSPENSIONS = (SUSPEND_THROUGH, SUSPEND_BEFORE, SUSPEND_STATUS)
_ENDS = (END_INCLUSIVE, END_EXCLUSIVE)
_DELEGATIONS = (DELEGATE_ALL, DELEGATE_OWNED, DELEGATE_NONE)

_ADMIN = "admin"
_EDITOR = "editor"
_EVERY_DOC = "*"


def _choice(name: str, value, allowed: tuple) -> None:
    if not isinstance(value, str) or value not in allowed:
        raise ValueError(f"{name}: {value!r} is not one of {', '.join(allowed)}")


def _flag(name: str, value) -> None:
    if value is not True and value is not False:
        raise ValueError(f"{name}: {value!r} is not True or False")


