class Rules:
    roles: str
    suspension: str
    ends: str
    delegation: str
    blank_team: bool
    wildcard_admin: bool

    def __post_init__(self):
        _choice("roles", self.roles, _ROLES)
        _choice("suspension", self.suspension, _SUSPENSIONS)
        _choice("ends", self.ends, _ENDS)
        _choice("delegation", self.delegation, _DELEGATIONS)
        _flag("blank_team", self.blank_team)
        _flag("wildcard_admin", self.wildcard_admin)


